INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(30201, 'Numbers 1:10', 'Numbers', 1, 10, 'د یوسف د زامنو څخه: د افرایم د قبیلې څخه الیشمع د عمیهود زوی د منسي د قبیلې څخه جملی ییل د فدهصور زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30202, 'Numbers 1:11', 'Numbers', 1, 11, 'د بنیامین د قبیلې څخه ابیدان د جدعوني زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30203, 'Numbers 1:12', 'Numbers', 1, 12, 'د دان د قبیلې څخه اخیعزر د عمیشدای زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30204, 'Numbers 1:13', 'Numbers', 1, 13, 'د اشیر د قبیلې څخه فجعییل د عکران زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30205, 'Numbers 1:14', 'Numbers', 1, 14, 'د جاد د قبیلې څخه الیاساف د دعویل زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30206, 'Numbers 1:15', 'Numbers', 1, 15, 'د نفتالي د قبیلې څخه اخیرع د عینان زوی.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30207, 'Numbers 1:16', 'Numbers', 1, 16, 'دا خلک قبیلوي مشران وو چې د اسراییلو د قوم څخه د دې کار دپاره وټاکل شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30208, '1 Chronicles 27:2', '1 Chronicles', 27, 2, 'په لومړۍ میاشت کې د زبدي ییل زوی یشوبعام،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30209, '1 Chronicles 27:3', '1 Chronicles', 27, 3, 'چې د فارص د اولادې څخه ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30210, '1 Chronicles 27:4', '1 Chronicles', 27, 4, 'په دوهمه میاشت کې اخوخي دودای چې مرستیال یې مقلوت ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30211, '1 Chronicles 27:5', '1 Chronicles', 27, 5, 'په درېمه میاشت کې د یهویاداع کاهن زوی بنایاه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30212, '1 Chronicles 27:6', '1 Chronicles', 27, 6, 'هغه یو جنګیالی ؤ او د دېرشو جنګیالیو مشر ؤ. د هغه د فرقې مسوول د هغه زوی عمیزاباد ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30213, '1 Chronicles 27:7', '1 Chronicles', 27, 7, 'په څلورمه میاشت کې د یوآب ورور عساهیل چې وروسته د هغه زوی زبدیا د هغه په ځای قوماندان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30214, '1 Chronicles 27:8', '1 Chronicles', 27, 8, 'په پنځمه میاشت کې د یزراح د طایفې څخه شمهوت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30215, '1 Chronicles 27:9', '1 Chronicles', 27, 9, 'په شپږمه میاشت کې د عقیش زوی عیرا له تقوع څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30216, '1 Chronicles 27:10', '1 Chronicles', 27, 10, 'په اوومه میاشت کې حالز فلوني د افرایم له قبیلې څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30217, '1 Chronicles 27:11', '1 Chronicles', 27, 11, 'په اتمه میاشت کې حوشاتي سبکای د زارح له طایفې څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30218, '1 Chronicles 27:12', '1 Chronicles', 27, 12, 'په نهمه میاشت کې د بنیامین په سیمه کې ابیعزر له عناتوت څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30219, '1 Chronicles 27:13', '1 Chronicles', 27, 13, 'په لسمه میاشت کې نطوفاتي مهرای د زارح له طایفې څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30220, '1 Chronicles 27:14', '1 Chronicles', 27, 14, 'په یوولسمه میاشت کې د افرایم په سیمه کې بنایاه له فرعاتون څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30221, '1 Chronicles 27:15', '1 Chronicles', 27, 15, 'په دولسمه میاشت کې نطوفاتي خلدای چې د عتني ییل یوه اولاده وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30222, '1 Chronicles 27:25', '1 Chronicles', 27, 25, 'د عدییل زوی عزموت د پاچا د شاهي ګودامونو مسوول ؤ. د عزیا زوی یوناتان د پاچا د نورو تحویلخانو چې په ښارګوټو، کلیو او د څارنې په برجونو کې وې، مسوول ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30223, '1 Chronicles 27:26', '1 Chronicles', 27, 26, 'د کلوب زوی عزري د هغو کارګرانو مسوول ؤ چې د پاچا په کروندو کې یې کښت کاوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30224, '1 Chronicles 27:27', '1 Chronicles', 27, 27, 'له رامه څخه شمعي د انګورو د تاکونو مسوول ؤ او له شفام څخه زبدي د انګورو د شرابو د ذخیره کولو مسوول ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30225, '1 Chronicles 27:28', '1 Chronicles', 27, 28, 'له جدر څخه بعل حانان د غرونو په لوېدیځو لمنو کې د زیتونو د تېلو او د انځر د ونو مسوول ؤ او یوآش د زیتونو د تېلو د ذخیره کولو مسوول ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30226, '1 Chronicles 27:29', '1 Chronicles', 27, 29, 'له شارون څخه شطرای د هغو پادو مسوولیت په غاړه درلود چې د شارون په ډاګونو کې څرېدلې او د عدلائي زوی شافاط د هغو پادو مسوولیت په غاړه درلود چې په درو کې ساتل کېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30227, '1 Chronicles 27:30', '1 Chronicles', 27, 30, 'اسماعیلي عوبیل د اوښانو مسوول ؤ او د میرونوت څخه یحدیای د خرو مسوول ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30228, '1 Chronicles 27:31', '1 Chronicles', 27, 31, 'هاجري یازیز د رمو مسوول ؤ. دا پورته ذکر شوي کسان د داود پاچا د شتمنۍ ناظران وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30229, 'Numbers 33:15', 'Numbers', 33, 15, 'هغوی د رفیدیم څخه لاړل او په اخر کې د سینا دښتې ته ورسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30230, 'Numbers 33:37', 'Numbers', 33, 37, 'کله چې هغوی د قادش څخه لاړل، نو د هور د غره په څنګ کې یې د ادوم په سرحد کې خېمې ودرولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30231, 'Numbers 33:38', 'Numbers', 33, 38, 'دا هغه ځای دی چې څښتن هارون کاهن ته امر وکړ چې د غره سرته وخېژي. هارون هلته د پنځمې میاشتې په لومړۍ ورځ څلوېښت کاله وروسته له دې چې اسراییلیان د مصر څخه تللي وو، مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30232, 'Numbers 33:39', 'Numbers', 33, 39, 'په هغه وخت کې هارون د یوسلو درویشتو کالو په عمر ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30233, 'Numbers 33:48', 'Numbers', 33, 48, 'او په اخر کې د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30234, 'Numbers 33:49', 'Numbers', 33, 49, 'د هغوی کمپ د بیت یشیموت څخه تر آبل شطیم پورې غزېدلی ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30235, '2 Chronicles 1:16', '2 Chronicles', 1, 16, 'د سلیمان سوداګرانو اسونه د مصر او ترکیې څخه راوستل. بیا به شاهي سوداګرانو هغه په یوه مناسبه بیه د هغو څخه اخیستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30236, '2 Chronicles 1:17', '2 Chronicles', 1, 17, 'هغوی به د مصر څخه یوه جنګي ګاډۍ د سپینو زرو په شپږ سوه سکو او یو اس به یې د سپینو زرو په یوسلو پنځوسو سکو اخیستل. همدارنګه ځینې به یې د حیتیانو او سوریایانو په پاچاهانو بېرته خرڅول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30237, '1 Chronicles 3:1', '1 Chronicles', 3, 1, 'دا د داود زامن وو چې په حبرون کې زېږېدلي وو: مشر یې امنون نومېده چې مور یې اخینوعم له یزرعیل څخه وه؛ دوهم یې دانیال ؤ چې مور یې ابیجایل د کرمل څخه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30238, '1 Chronicles 3:2', '1 Chronicles', 3, 2, 'درېم یې ابشالوم ؤ چې مور یې معکه نومېدله چې د جشور د پاچا تلمای لور وه؛ څلورم یې ادونیا ؤ چې مور یې حجیت نومېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30239, '1 Chronicles 3:3', '1 Chronicles', 3, 3, 'پنځم یې شفطیا ؤ چې مور یې ابیطال نومېدله او شپږم یې یترعام ؤ چې مور یې عجله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30240, '1 Kings 7:2', '1 Kings', 7, 2, 'د ماڼۍ هغه سالون چې د لبنان د ځنګل د سالون په نوم یادېده څلورڅلوېښت متره اوږدوالی، دوه ویشت متره سور او دیارلس نیم متره لوړوالی درلود. هغه د سبر د ونو د ستنو څلور قطاره درلودل چې د سبر تیران ورباندې پراته وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30241, '1 Kings 7:3', '1 Kings', 7, 3, 'د دې سالون د سبر د لرګیو بام د تیرانو دپاسه ؤ او دا تیران په ستنو باندې پراته وو. ټول پنځه څلوېښت تیران او په هر یو قطار کې پنځلس تیران وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30242, '1 Kings 7:40', '1 Kings', 7, 40, 'حورام همدارنګه تشتونه، بېلچې او د وینو د شیندلو کاسې جوړې کړې. نو حورام هغه ټول کارونه پای ته ورسول چې د سلیمان پاچا دپاره یې د څښتن د کور په خاطر په خپله غاړه اخیستي وو:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30243, '1 Kings 7:41', '1 Kings', 7, 41, 'دوه ستنې د ستنو په سرونو باندې د کاسو په شان دوه تاجونه د جالیو دوه سېټونه، د ستنو په سرونو باندې د سینګارولو دپاره د کاسو په شان دوه تاجونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30244, '1 Kings 7:42', '1 Kings', 7, 42, 'د دوو سېټونو جالیو دپاره څلور سوه برنجي انار. د هرې جالۍ دپاره د برنجي انارو دوه قطارونه چې د ستنو په سرونو باندې د کاسو په شان تاجونه د ښکلا دپاره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30245, '1 Kings 7:43', '1 Kings', 7, 43, 'لس ګاډۍ د هغو د لسو تشتونو سره', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30246, '1 Kings 7:44', '1 Kings', 7, 44, 'ټانکۍ او د هغې لاندې دولس برنجي غویان', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30247, '1 Kings 7:45', '1 Kings', 7, 45, 'لوښي، بېلچې او د وینو د شیندلو دپاره کاسې. د څښتن د کور دا ټول سامان چې حورام د سلیمان پاچا دپاره جوړ کړی ؤ، د صیقل شویو برنجو څخه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30248, 'Leviticus 22:26', 'Leviticus', 22, 26, 'څښتن موسی ته وویل:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30249, 'Leviticus 22:27', 'Leviticus', 22, 27, '«کله چې یو خوسی، یو وری یا یوه وزه پیدا شي، د خپلې مور سره دې اووه ورځې پاتې شي. له اتمې ورځې څخه به هغه د یوې داسې نذرانې په توګه د منلو وړ وي چې څښتن ته په اور باندې تیاریږي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30250, 'Genesis 6:9', 'Genesis', 6, 9, 'دا د نوح کیسه ده. نوح په خپله زمانه کې نېک او پرهېزګار سړی ؤ او خدای ته ډېر نژدې ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30251, 'Genesis 6:10', 'Genesis', 6, 10, 'هغه درې زامن درلودل: سام، حام او یافت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30252, 'Genesis 6:19', 'Genesis', 6, 19, 'د ټولو ژوندیو مخلوقاتو څخه یوه یوه جوړه نر او ښځه د ځان سره کشتۍ ته راوله، ترڅو هغه ژوندي وساتې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30253, 'Genesis 6:20', 'Genesis', 6, 20, 'د هر ډول مرغانو، حیواناتو او خزندو څخه به دوه دوه تاته راشي، ترڅو هغه ژوندي وساتې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30254, 'Genesis 21:9', 'Genesis', 21, 9, 'خو ساره ولیدل چې د مصرۍ هاجرې زوی په اسحاق باندې ملنډې وهي،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30255, 'Genesis 21:10', 'Genesis', 21, 10, 'نو هغې ابراهیم ته وویل: «دغه وینځه او د هغې زوی وشړه، ځکه چې د دې وینځې زوی دې زما د زوی اسحاق سره هېڅکله په میراث کې شریک نه شي.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30256, 'Exodus 9:23', 'Exodus', 9, 23, 'کله چې موسی خپله امسا د اسمان خواته اوږده کړه، څښتن تندر او ږلۍ نازله کړه او برېښنا په ځمکه باندې پړکېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30257, 'Exodus 9:24', 'Exodus', 9, 24, 'ږلۍ وورېدله او برېښنا په دوامداره توګه پړکېدله. دا د مصر په تاریخ کې تر ټولو بد توفان ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30258, '2 Kings 22:5', '2 Kings', 22, 5, 'هغوی ته ووایه چې دا پیسې هغو ټېکدارانو ته ورکړي چې د څښتن د کور د بیا جوړونې مسوولیت لري. دوی باید هغه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30259, '2 Kings 22:6', '2 Kings', 22, 6, 'نجارانو او ګلکارانو ته ورکړي او همدارنګه هغه لرګي او توږل شوې تیږې دې واخلي چې په بیا جوړونه کې ورڅخه کار اخیستل کیږي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30260, 'Exodus 28:33', 'Exodus', 28, 33, 'د چپنې د لمنې په څنډه باندې د ابي، بانجاني او سرو وړیو څخه داسې انار جوړ کړه چې په منځ کې یې د سرو زرو زنګونه وي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30261, 'Exodus 28:34', 'Exodus', 28, 34, 'د سرو زرو زنګونه او انار دې د چپنې د لمنې ګردچاپېره د یو بل ترمنځ راشي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30262, 'Leviticus 18:12', 'Leviticus', 18, 12, 'د خپل پلار د خور سره زنا مه کوئ، هغه ستاسو د پلار نژدې خپلوانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30263, 'Leviticus 18:13', 'Leviticus', 18, 13, 'د خپلې مور د خور سره زنا مه کوئ، ځکه چې هغه ستاسو د مور نژدې خپلوانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30264, 'Exodus 39:24', 'Exodus', 39, 24, 'هغوی د چپنې د لمنې په څنډه باندې د ابي، بانجاني او سرو وړیو او ښه کتان څخه انار جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30265, 'Exodus 39:25', 'Exodus', 39, 25, 'د سوچه سرو زرو څخه یې زنګونه جوړ کړل او هغه یې د لمنې په څنډه باندې د انارو ترمنځ ونښلول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30266, 'Exodus 39:26', 'Exodus', 39, 26, 'لکه څنګه چې څښتن موسی ته حکم کړی ؤ، زنګونه او انار د هغې چپنې د لمنې په څنډه باندې چې د خدمت کولو دپاره به اغوستل کېدله، د یو بل ترمنځ راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30267, 'Exodus 12:19', 'Exodus', 12, 19, 'اووه ورځې باید ستاسو په کورونو کې خمیره پیدا نه شي. ځکه که چېرې څوک که هغه پردی وي او یا اسراییلی وي خمیره ډوډۍ وخوري، هغه به د اسراییلو د قوم څخه وشړل شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30268, 'Exodus 12:20', 'Exodus', 12, 20, 'هېڅ داسې شی مه خورئ چې د خمیرې څخه تیار شوی وي. هر چېرته چې تاسو اوسېږئ باید فطیره ډوډۍ وخورئ.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30269, 'Numbers 2:3', 'Numbers', 2, 3, 'د یهودا د کمپ ډلې دې په ختیځ کې د لمرخاته خواته د خپل بیرغ لاندې خېمې ودروي. د یهودا د خلکو مشر د عمیناداب زوی نحشون دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30270, 'Numbers 2:4', 'Numbers', 2, 4, 'د هغه د ډلې شمېر ۷۴۶۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30271, 'Numbers 2:5', 'Numbers', 2, 5, 'د یساکار قبیله به د هغوی په څنګ کې خېمې ودروي. د یساکار د خلکو مشر د صوغر زوی نتناییل دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30272, 'Numbers 2:6', 'Numbers', 2, 6, 'د هغه د ډلې شمېر ۵۴۴۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30273, 'Numbers 2:7', 'Numbers', 2, 7, 'ورپسې به د زبولون قبیله وي. د زبولون د خلکو مشر د حیلون زوی الیاب دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30274, 'Numbers 2:8', 'Numbers', 2, 8, 'د هغه د ډلې شمېر ۵۷۴۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30275, 'Numbers 2:9', 'Numbers', 2, 9, 'هغه ټول کسان چې د یهودا کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۸۶۴۰۰ تنه دی. لومړی به دوی روان شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30276, 'Numbers 2:10', 'Numbers', 2, 10, 'د روبین د کمپ ډلې به په جنوب کې د خپل بیرغ لاندې وي. د روبین د خلکو مشر د شدییور زوی الیصور دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30277, 'Numbers 2:11', 'Numbers', 2, 11, 'د هغه د ډلې شمېر ۴۶۵۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30278, 'Numbers 2:12', 'Numbers', 2, 12, 'د شمعون قبیله به د هغوی په څنګ کې خېمې ودروي. د شمعون د خلکو مشر د صوریشدای زوی شلومییل دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
