(30280, 'Numbers 2:14', 'Numbers', 2, 14, 'ورپسې به د جاد قبیله وي. د جاد د خلکو مشر د دعویل زوی الیاساف دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30281, 'Numbers 2:15', 'Numbers', 2, 15, 'د هغه د ډلې شمېر ۴۵۶۵۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30282, 'Numbers 2:16', 'Numbers', 2, 16, 'هغه ټول کسان چې د روبین کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۵۱۴۵۰ تنه دی. دوهم به دوی روان شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30283, 'Numbers 2:18', 'Numbers', 2, 18, 'د افرایم د کمپ ډلې به په لوېدیځ کې د خپل بیرغ لاندې وي. د افرایم د خلکو مشر د عمیهود زوی الیشمع دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30284, 'Numbers 2:19', 'Numbers', 2, 19, 'د هغه د ډلې شمېر ۴۰۵۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
