(30287, 'Numbers 2:22', 'Numbers', 2, 22, 'ورپسې به د بنیامین قبیله وي. د بنیامین د خلکو مشر د جدعوني زوی ابیدان دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30288, 'Numbers 2:23', 'Numbers', 2, 23, 'د هغه د ډلې شمېر ۳۵۴۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30289, 'Numbers 2:24', 'Numbers', 2, 24, 'هغه ټول کسان چې د افرایم کمپ ته د هغوی د ډلو له مخې ورکړل شوي دي، د هغوی شمېر ۱۰۸۱۰۰ تنه دی. درېم به دوی روان شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30290, 'Numbers 2:25', 'Numbers', 2, 25, 'د دان د کمپ ډلې به په شمال کې د خپل بیرغ لاندې وي. د دان د خلکو مشر د عمیشدای زوی اخیعزر دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30291, 'Numbers 2:26', 'Numbers', 2, 26, 'د هغه د ډلې شمېر ۶۲۷۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30292, 'Numbers 2:27', 'Numbers', 2, 27, 'د اشیر قبیله به د هغوی په څنګ کې خېمې ودروي. د اشیر د خلکو مشر د عکران زوی فجعییل دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30293, 'Numbers 2:28', 'Numbers', 2, 28, 'د هغه د ډلې شمېر ۴۱۵۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30294, 'Numbers 2:29', 'Numbers', 2, 29, 'ورپسې به د نفتالي قبیله وي. د نفتالي د خلکو مشر د عینان زوی اخیرع دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30295, 'Numbers 2:30', 'Numbers', 2, 30, 'د هغه د ډلې شمېر ۵۳۴۰۰ تنه دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30296, 'Numbers 2:31', 'Numbers', 2, 31, 'هغه ټول کسان چې د دان کمپ ته ورکړل شوي دي، د هغوی شمېر ۱۵۷۶۰۰ تنه دی. هغوی به د خپلو بیرغونو لاندې په اخر کې روان شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30297, 'Song of Songs 8:1', 'Song of Songs', 8, 1, 'اے کاش چې تۀ زما دپاره لکه د ورور په شان وينه، چا چې ما سره د مور په سينه خولۀ اېښې وينه. نو کله چې تۀ ما په لار کښې ليدلے نه نو ما به تۀ ښکلولے نه او چا به هم په ما باندې اِعتراض کولو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30298, 'Song of Songs 8:2', 'Song of Songs', 8, 2, 'ما به تۀ د خپل ماشومتوب کور ته راوستے وينه، او هلته به تا ما ته سبق ښودلے وونه. ما به درته د څښلو دپاره مزېدار مے درکړى وُونه، د خپلو خوږو انارو شربت به مې درکړے وونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30299, 'Song of Songs 8:3', 'Song of Songs', 8, 3, 'ستا ګس لاس به زما د سر لاندې وونه، او ستا ښى لاس به ځانته راغاړه ايستمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30300, 'Song of Songs 8:4', 'Song of Songs', 8, 4, 'اے د يروشلم پېغلو، ما سره وعده وکړئينه، مينه مۀ رابېداروئينه، ترڅو چې يې ونۀ غواړينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');